TITLE_NOISE_WORDS = (
    "深圳政府在线",
    "深圳市人民政府门户网站",
    "宝安区人民政府门户网站",
    "政府在线",
    "信息公开",
    "政务公开",
    "网站首页",
    "当前位置",
    "政策文件",
    "政策法规",
    "通知公告",
)


def clean_policy_title(title: str) -> str:
    raw = remove_urls(re.sub(r"\s+", " ", title or "")).strip(" -_|：:，。")
    if not raw or "$" in raw or "function" in raw.lower():
        return ""
    raw = re.split(r"[|_]+", raw)[0].strip(" -—_|")
    for suffix in ("-深圳政府在线", "_深圳政府在线", "-深圳市人民政府门户网站", "_深圳市人民政府门户网站"):
        raw = raw.replace(suffix, "")
    for word in TITLE_NOISE_WORDS:
        raw = raw.replace(word, " ")
    raw = re.sub(r"\s+", " ", raw).strip(" -—_|")
    if len(raw) < 6 or len(raw) > 120:
        return ""
    if has_boilerplate(raw) and not any(token in raw for token in ("通知", "办法", "措施", "规定", "方案", "细则", "指南")):
        return ""
    return raw[:90]


def short_policy_subject(policy_title: str) -> str:
    if not policy_title:
        return ""
    quoted = re.search(r"《([^》]{4,38})》", policy_title)
    if quoted:
        return quoted.group(1).strip()
    subject = policy_title
    subject = re.sub(r"^(深圳市|深圳|福田区|南山区|龙华区|盐田区|大鹏新区|前海|国家税务总局深圳市税务局)", "", subject)
    subject = re.sub(r".*?关于", "", subject)
    subject = re.sub(r"(的通知|通知|办法|规定|措施|细则|方案|指南)$", "", subject)
    subject = re.sub(r"[\s,，。；;：:]+", "", subject)
    return subject[:24]


def policy_excerpt(text: str, limit: int = 220) -> str:
    cleaned = clean_policy_text(text)
    if not cleaned:
        return ""
    sentences = [part.strip(" ，。；：") for part in re.split(r"(?<=[。！？；])", cleaned) if part.strip()]
    keywords = ("扶持", "支持", "资助", "补贴", "奖励", "申报", "企业", "项目", "资金", "产业", "人才", "金融", "税", "住房", "商务", "创新")
    selected: list[str] = []
    for sentence in sentences:
        if has_boilerplate(sentence) or len(sentence) < 22 or len(sentence) > 180:
            continue
        if any(keyword in sentence for keyword in keywords):
            selected.append(sentence)
        if len(selected) >= 2:
            break
    if not selected:
        for sentence in sentences:
            if not has_boilerplate(sentence) and 22 <= len(sentence) <= 180:
                selected.append(sentence)
            if len(selected) >= 2:
                break
    excerpt = "。".join(selected)[:limit]
    return excerpt.strip(" ，。；：")


def subsidy_highlight(text: str, limit: int = 150) -> str:
    cleaned = clean_policy_text(text)
    if not cleaned:
        return ""
    sentences = [part.strip(" ，。；：") for part in re.split(r"(?<=[。！？；])", cleaned) if part.strip()]
    money_pattern = re.compile(r"(最高|不超过|给予|资助|补贴|奖励|贴息|扶持)[^。！？；]{0,55}?(万元|元|%|％)")
    support_words = ("资助", "补贴", "奖励", "扶持", "贴息", "资金", "补助")
    for sentence in sentences:
        if has_boilerplate(sentence) or len(sentence) > 180:
            continue
        if any(word in sentence for word in support_words) and money_pattern.search(sentence):
            return sentence[:limit].strip(" ，。；：")
    for sentence in sentences:
        if has_boilerplate(sentence) or len(sentence) > 180:
            continue
        if any(word in sentence for word in support_words):
            return sentence[:limit].strip(" ，。；：")
    return ""

def remove_old_title_years(text: str) -> str:
    cleaned = OLD_TITLE_YEAR_RE.sub("", text or "")
    cleaned = re.sub(r"[，,、：:；;\s]+", "，", cleaned)
    return cleaned.strip(" ，,、：:；;-—_（）()[]【】")


BRACKET_PAIRS = {"（": "）", "《": "》", "【": "】", "(": ")", "[": "]"}
REVERSE_BRACKET_PAIRS = {closing: opening for opening, closing in BRACKET_PAIRS.items()}


def remove_unbalanced_brackets(text: str) -> str:
    """Drop unmatched bracket characters so generated titles/articles do not contain half brackets."""
    chars = list(text or "")
    stack: list[tuple[str, int]] = []
    remove_indexes: set[int] = set()
    for index, char in enumerate(chars):
        if char in BRACKET_PAIRS:
            stack.append((char, index))
        elif char in REVERSE_BRACKET_PAIRS:
            if stack and stack[-1][0] == REVERSE_BRACKET_PAIRS[char]:
                stack.pop()
            else:
                remove_indexes.add(index)
    remove_indexes.update(index for _, index in stack)
    return "".join(char for index, char in enumerate(chars) if index not in remove_indexes)



PARAPHRASE_REPLACEMENTS = [
    ("建议", ["不妨", "可以", "建议", "最好"]),
    ("提前", ["尽早", "先一步", "在窗口期前", "趁现在"]),
    ("材料", ["资料", "材料", "申报材料", "支撑材料"]),
    ("政策匹配", ["政策适配", "机会匹配", "政策筛选", "项目匹配"]),
    ("资质评估", ["资质测评", "条件预判", "申报体检", "资格评估"]),
    ("研发费用", ["研发投入", "研发经费", "研发支出", "研发费用"]),
    ("项目资料", ["项目档案", "项目证据", "项目资料", "项目支撑"]),
    ("费用归集", ["费用整理", "经费归集", "投入归集", "费用归集"]),
    ("材料缺口", ["资料短板", "材料缺口", "材料缺口", "资料缺口"]),
]


def variant_phrase(text: str, seed: int) -> str:
    """Lightly rewrite wording so same ideas do not become identical paragraphs without touching brand names."""
    protected = {
        "深圳金赋": "__JINFU__",
        "金赋补贴宝": "__JINFU_CTA__",
        "补贴平台": "__SUBSIDY_PLATFORM__",
    }
    rewritten = text
    for source, token in protected.items():
        rewritten = rewritten.replace(source, token)
    for offset, (source, choices) in enumerate(PARAPHRASE_REPLACEMENTS):
        if source in rewritten:
            replacement = choices[(seed + offset) % len(choices)]
            if replacement != source:
                rewritten = rewritten.replace(source, replacement, 1)
    for source, token in protected.items():
        rewritten = rewritten.replace(token, source)
    return rewritten


def reorder_sentences(text: str, seed: int) -> str:
    sentences = [part for part in re.split(r"(?<=[。！？])", text) if part]
    if len(sentences) < 3:
        return text
    # Keep the opening sentence readable, but rotate the middle so duplicated paragraphs differ.
    middle = sentences[1:-1]
    shift = seed % len(middle)
    if shift:
        middle = middle[shift:] + middle[:shift]
    return "".join([sentences[0], *middle, sentences[-1]])


def cleanup_generated_wording(text: str) -> str:
    fixes = {
        "证明证明文件": "证明文件",
        "证明申报依据": "证明材料",
        "支撑文件清单": "材料清单",
        "项目支撑文件": "项目资料",
        "支撑支撑材料": "支撑材料",
        "支撑资料材料": "支撑材料",
        "申报支撑文件": "申报材料",
        "申报申报材料": "申报材料",
        "申报申报依据": "申报材料",
        "申报依据规划": "申报规划",
        "证明文件清单": "材料清单",
        "证明文件体检": "材料体检",
        "证明文件却": "材料却",
        "哪些证明文件": "哪些材料",
        "哪些申报依据": "哪些材料",
        "申报依据说服力": "材料说服力",
        "申报依据里": "材料里",
        "写申报依据": "写材料",
        "直接写证明文件": "直接写材料",
        "可以企业": "建议企业",
        "可以机构": "建议机构",
        "深圳金赋不妨": "深圳金赋建议",
        "深圳金赋最好": "深圳金赋建议",
        "深圳金赋可以": "深圳金赋可",
        "深圳金赋更适合企业": "深圳金赋建议企业",
        "深圳金赋更适合机构": "深圳金赋建议机构",
        "深圳金赋更适合先": "深圳金赋建议先",
        "深圳金赋更适合": "深圳金赋建议",
    }
    cleaned = text
    for bad, good in fixes.items():
        cleaned = cleaned.replace(bad, good)
    return cleaned


def diversify_paragraph(text: str, seed: int, force_reorder: bool = False) -> str:
    diversified = variant_phrase(text, seed)
    if force_reorder or seed % 2:
        diversified = reorder_sentences(diversified, seed)
    return remove_unbalanced_brackets(cleanup_generated_wording(diversified)).strip()


CTA_EXPANSIONS = [
    "系统会先把主体条件、金额口径、资料现状和风险点放在同一张清单里，企业再决定是否启动正式申报，节奏会稳很多。",
    "评估后可以看到哪些资料已经能用、哪些还需要补强，也能顺手把区级、市级、省级等后续政策放进年度规划。",
    "这样做的好处是先判断机会大小，再安排财务、项目负责人和行政同事分工，避免临近申报期才反复补证明。",
    "如果暂时不满足条件，也能把差距记录下来，后续围绕经营数据、费用台账、资质证明和项目成果继续培育。",
    "企业不必把所有政策都追一遍，先让补贴平台筛出更匹配的方向，再把精力放在最值得推进的项目上。",
    "一次评估也能帮助老板看清投入和政策资金之间的关系，让经营成本不只是账面支出，而是有机会形成资金回流。",
    "后续如果政策窗口打开，企业可以直接沿着清单补材料、核金额、排节点，减少跨部门沟通成本。",
    "这也是一次年度资料体检，把分散在财务、业务、行政和管理层手里的信息先串起来。",
    "平台会根据企业画像持续更新推荐结果，后面有配套奖励、专项资金或资质培育机会，也更容易及时发现。",
    "先做轻量评估，再决定是否深度准备，既能保留拿补贴机会，也能控制申报投入。",
]


def expand_cta(paragraph: str, seed: int) -> str:
    if "金赋补贴宝" not in paragraph:
        return paragraph
    expansion = CTA_EXPANSIONS[seed % len(CTA_EXPANSIONS)]
    if expansion in paragraph:
        expansion = CTA_EXPANSIONS[(seed + 3) % len(CTA_EXPANSIONS)]
    return f"{paragraph}{expansion}"


def paragraph_signature(text: str) -> str:
    """Create a loose signature to catch repeated long paragraphs even after small punctuation changes."""
    compact = re.sub(r"[，。！？；：、,.!?;:\s]+", "", text or "")
    compact = re.sub(r"\d+(?:\.\d+)?", "#", compact)
    compact = compact.replace("深圳金赋", "").replace("金赋补贴宝", "").replace("补贴平台", "")
    return compact[:120]


def rewrite_repeated_paragraph(text: str, seed: int, attempt: int) -> str:
    """Rewrite repeated paragraphs with different sentence order and natural connectors."""
    connectors = [
        "换个更实际的说法，",
        "放到企业经营里看，",
        "老板更关心的是，",
        "财务同事可以这样理解：",
        "如果把账算细一点，",
        "从拿补贴的角度看，",
        "别小看这一点，",
        "真正落到申报时，",
        "换到项目负责人视角，",
        "说得接地气一点，",
    ]
    candidate = variant_phrase(text, seed + attempt * 11)
    if attempt % 2 == 0:
        candidate = reorder_sentences(candidate, seed + attempt)
    if not candidate.startswith(tuple(connectors)):
        candidate = connectors[(seed + attempt) % len(connectors)] + candidate
    return remove_unbalanced_brackets(cleanup_generated_wording(candidate)).strip()


def vary_repeated_opening(text: str, seed: int) -> str:
    """Avoid many paragraphs starting with the same phrase in one batch."""
    starters = [
        "先看重点：",
        "别急，先把账算清楚：",
        "换个角度想，",
        "对企业来说，",
        "这时候要看的不是热闹，",
        "拿补贴之前，",
        "如果企业已经有动作，",
        "材料准备上，",
        "更现实一点，",
        "这类机会最怕被忽略，",
    ]
    if len(text) < 90:
        return text
    # Do not stack connectors if paragraph already starts conversationally.
    if text.startswith(tuple(starters)):
        return text
    return starters[seed % len(starters)] + text


def polish_article_paragraphs(
    paragraphs: list[str],
    article_index: int,
    seen_paragraphs: set[str] | None = None,
    seen_signatures: set[str] | None = None,
    opening_counts: dict[str, int] | None = None,
    preserve_sentence_order: bool = False,
) -> list[str]:
    """Diversify wording, lengthen CTAs, and avoid repeated or too-similar paragraphs across a batch."""
    polished: list[str] = []
    local_seen: set[str] = set()
    local_signatures: set[str] = set()
    seen = seen_paragraphs if seen_paragraphs is not None else set()
    signatures = seen_signatures if seen_signatures is not None else set()
    openings = opening_counts if opening_counts is not None else {}
    for paragraph_index, paragraph in enumerate(paragraphs):
        seed = article_index * 17 + paragraph_index * 5
        candidate = expand_cta(paragraph, seed)
        candidate = variant_phrase(candidate, seed) if preserve_sentence_order else diversify_paragraph(candidate, seed)
        candidate = remove_unbalanced_brackets(cleanup_generated_wording(candidate)).strip()
        attempts = 0
        signature = paragraph_signature(candidate)
        while (
            len(candidate) > 80
            and (candidate in seen or candidate in local_seen or signature in signatures or signature in local_signatures)
            and attempts < 8
        ):
            candidate = rewrite_repeated_paragraph(candidate, seed, attempts)
            signature = paragraph_signature(candidate)
            attempts += 1
        opening = re.sub(r"[，。！？；：、,.!?;:\s].*$", "", candidate[:18])
        if len(candidate) > 90 and opening:
            openings[opening] = openings.get(opening, 0) + 1
            if openings[opening] > 2:
                candidate = vary_repeated_opening(candidate, seed + openings[opening])
                signature = paragraph_signature(candidate)
        if len(candidate) > 80:
            seen.add(candidate)
            local_seen.add(candidate)
            signatures.add(signature)
            local_signatures.add(signature)
        polished.append(candidate)
    return polished




def ensure_brand_cta(paragraphs: list[str], article_index: int) -> list[str]:
    """Ensure every generated article keeps the brand CTA without repeating the same closing wording."""
    if any("补贴平台" in p for p in paragraphs) and any("金赋补贴宝" in p for p in paragraphs):
        return paragraphs
    cta_options = [
        "企业也可以关注「金赋补贴宝」，进入补贴平台先做一次资质评估，把外资金额、主体口径和材料缺口放进同一张清单里看。",
        "如果想更快判断机会大小，可关注「金赋补贴宝」进入补贴平台，先看自身条件与政策门槛是否匹配。",
        "后续准备申报前，建议关注「金赋补贴宝」并进入补贴平台，把奖励测算、资料状态和风险提醒一起核清。",
        "想少走弯路，可以关注「金赋补贴宝」进入补贴平台，让系统先帮企业筛一遍补贴机会和材料短板。",
    ]
    addition = cta_options[article_index % len(cta_options)]
    if paragraphs:
        paragraphs[-1] = f"{paragraphs[-1]}{addition}"
    else:
        paragraphs.append(addition)
    return paragraphs


OPENING_MOODS = [
    "先说个实在的判断：",
    "如果把它放到企业经营里看，",
    "这事别只交给资料员，",
    "换成老板视角，",
    "财务同事看到这里，可以先记一笔：",
    "项目负责人更该关注的是，",
    "说白了，",
    "有个容易被忽略的细节：",
    "别急着翻下一条政策，",
    "从拿补贴的角度看，",
    "更接地气一点讲，",
    "这类项目最怕什么？",
    "先别问能不能申，",
    "真正要提前做的，是",
    "如果企业已经做过相关工作，",
    "把时间线拉长一点看，",
    "别小看这个动作，",
    "对经办人来说，",
    "对管理层来说，",
    "如果想少走弯路，",
    "这不是一句口号，",
    "把材料摊开来看，",
    "先给企业提个醒：",
    "这个机会值不值得追，",
]


def opening_key(text: str) -> str:
    compact = re.sub(r"^[\s　‘’“”\'\"（(【\[]+", "", text or "")
    compact = re.sub(r"[，。！？；：、,.!?;:\s].*$", "", compact[:24])
    return compact[:10]


def vary_article_paragraph_openings(paragraphs: list[str], article_index: int) -> list[str]:
    """Make paragraph starts feel less templated inside one article.

    Handwritten builders sometimes produce good policy detail but still start several
    paragraphs with the same role label or structure. This pass only changes the
    front door of long paragraphs: it rotates short conversational leads, trims
    duplicate prefixes, and leaves brand/CTA wording intact.
    """
    varied: list[str] = []
    local_counts: dict[str, int] = {}
    role_prefix_re = re.compile(
        r"^(财务同事|项目负责人|技术团队|质量负责人|老板|行政同事|市场团队|标准负责人|申报经办人|研发负责人|品牌负责人|运营团队|管理层|资料负责人|合规同事|业务部门)"
        r"(先看这个点|可以这样拆|别漏这个细节|要提前留痕|先把资料排队|可以换个角度看|最好先算一笔账|别只看表面金额|要把证据链拉直|可以先做一次体检|更适合先核口径|要把时间线理清)，?"
    )
    for idx, paragraph in enumerate(paragraphs):
        text = paragraph.strip()
        if idx == 0 or len(text) < 90:
            varied.append(text)
            continue
        text = role_prefix_re.sub("", text).lstrip("，,。；;：: ")
        key = opening_key(text)
        local_counts[key] = local_counts.get(key, 0) + 1
        should_add_lead = local_counts[key] > 1 or idx % 2 == 0
        if should_add_lead and not text.startswith(tuple(OPENING_MOODS)):
            lead = OPENING_MOODS[(article_index * 7 + idx * 3) % len(OPENING_MOODS)]
            if lead.endswith("是"):
                text = f"{lead}{text}"
            elif lead.endswith("？"):
                text = f"{lead}{text}"
            else:
                text = f"{lead}{text}"
        varied.append(remove_unbalanced_brackets(cleanup_generated_wording(text)).strip())
    return varied


def enforce_batch_opening_variety(
    paragraphs: list[str],
    article_index: int,
    article_title: str,
    opening_counts: dict[str, int],
) -> list[str]:
    """Final pass to prevent repeated paragraph openings across a generated batch."""
    varied: list[str] = []
    title_hint = re.sub(r"[，。！？；：、,.!?;:\s]+", "", article_title)[:8] or "这类项目"
    leads = [
        f"从{title_hint}看，",
        f"围绕{title_hint}，",
        f"拿{title_hint}来算，",
        f"回到{title_hint}本身，",
        f"企业看{title_hint}，",
        f"如果盯住{title_hint}，",
        f"把{title_hint}放进预算表，",
        f"换到{title_hint}的场景，",
        f"想借{title_hint}拿补贴，",
        f"别让{title_hint}只停在文件里，",
    ]
    for idx, paragraph in enumerate(paragraphs):
        text = paragraph.strip()
        if len(text) < 50:
            varied.append(text)
            continue
        key = opening_key(text)
        opening_counts[key] = opening_counts.get(key, 0) + 1
        if opening_counts[key] > 1 and not text.startswith(tuple(leads)):
            lead = leads[(article_index + idx + opening_counts[key]) % len(leads)]
            text = f"{lead}{text}"
        varied.append(remove_unbalanced_brackets(cleanup_generated_wording(text)).strip())
    return varied

def normalize_article_title(title: str, fallback: str = "企业补贴机会，先做评估") -> str:
    cleaned = remove_old_title_years(title)
    if not cleaned:
        cleaned = remove_old_title_years(fallback) or "企业补贴机会，先做评估"
    cleaned = re.sub(r"\s+", "", cleaned).strip(" ，,、：:；;-—_（）()[]【】")
    cleaned = remove_unbalanced_brackets(cleaned[:TITLE_MAX_CHARS]).strip(" ，,、：:；;-—_（）()[]【】")
    if len(cleaned) < TITLE_MIN_CHARS:
        suffixes = ["补贴机会先评估", "专项资金先测算", "企业申报先体检", "材料口径先核清"]
        for suffix in suffixes:
            candidate = remove_unbalanced_brackets((cleaned + suffix)[:TITLE_MAX_CHARS]).strip(" ，,、：:；;-—_（）()[]【】")
            if len(candidate) >= TITLE_MIN_CHARS:
                cleaned = candidate
                break
    return cleaned or "企业补贴机会先评估"


