        "申报主体如果是企业，资助比例按不超过项目当年总投入的50%测算；如果是事业单位，自投经费不设强制性要求。企业要重点把年度投入、费用结构和自有资金安排讲清楚。",
        "这项计划采取核准与评审相结合的方式，不是简单提交材料就结束。单位申报、材料审核、专家评审、社会公示、政府决策，每一步都需要项目逻辑和证据支撑。",
