        f"深圳金赋服务{label}时会先做项目拆解：{company_lines[(variant - 1) % len(company_lines)]}{promotion_lines[(variant + 2) % len(promotion_lines)]}",
        f"{label}还要把风险提前说清：{risk_lines[(variant + 3) % len(risk_lines)]}",
        f"把{label}放进年度资金规划：重点科技创新类机构往往不是单一补贴项目，研发投入、场地租金、建设运营、设备采购、人才团队和贷款贴息都可能关联不同政策。先做总账，再排优先级，企业更容易把资金机会用起来。",
        endings[(variant - 1) % len(endings)],
